cd /Users/myankelev/Code/random/cipher-box-phase69
GSD_TOOLS=".claude/gsd-core/bin/gsd-tools.cjs"; [ -f "$GSD_TOOLS" ] || GSD_TOOLS="gsd-core/bin/gsd-tools.cjs"
gsd_run() { node "$GSD_TOOLS" "$@"; }
echo "===PLAN:PRE HOOKS (activeHooks only)==="
gsd_run loop render-hooks plan:pre --raw 2>/dev/null | node -e '
let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{
  try{const j=JSON.parse(s);const h=j.activeHooks||j.hooks||[];
    console.log("count:",h.length);
    for(const x of (h||[])){
      console.log("---");
      console.log("kind:",x.kind,"| capId:",x.capId,"| into:",x.into||"", "| blocking:",x.blocking);
      if(x.ref)console.log("ref:",JSON.stringify(x.ref));
      if(x.check)console.log("check:",JSON.stringify(x.check));
      if(x.when)console.log("when:",JSON.stringify(x.when));
      if(x.configValues)console.log("configValues:",JSON.stringify(x.configValues));
    }
  }catch(e){console.log("PARSE_ERR",e.message);console.log(s.slice(0,2000));}
});'
echo ""
echo "===UI PLAN GATE==="
gsd_run check ui-plan-gate "69" --raw 2>/dev/null || echo "no-ui-gate"

